    input  logic rst_n,
    input  logic req0,
    input  logic req1,
    input  logic retire,
    output logic grant0,
    output logic grant1
);

    logic prefer1;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant0  <= 1'b0;
            grant1  <= 1'b0;
            prefer1 <= 1'b0;
